lessons.solution:
setcpm(124/4)
const key = "C:minor"
const kick = s("bd bd bd [bd bd]").bank("RolandTR707")
const clap = s("~ cp ~ [cp cp]").bank("RolandTR707")
const hats = s("hh*8").bank("RolandTR707").gain(.4).lastOf(4, x => x.fast(2))
const toms = s("[~ lt] [~ mt] [~ lt] [~ ht]").bank("RolandTR808").gain(.6)
const riff = n("0 ~ 3 ~ 5 ~ 3 0").scale(key).s("piano").gain(.6)
const acid = n("0 0 7 0 3 0 7 5").scale(key).s("sawtooth").lpf(1200).lpq(10).octave(2)
stack(kick, clap, hats, toms, riff, acid)

